package io.colorsand.core

/**
 * The hand-made levels, easiest first. Each string is one tube, bottom to top; "" is an empty tube.
 * Color codes: see [SandColor]. Every level is checked to be solvable by the tests.
 *
 * After the last hand-made level, [get] continues with generated levels so the game never runs out.
 */
object Levels {
    val handMade: List<Level> = listOf(
        Level.parse(1, 4, "RRBB", "BBRR", ""),
        Level.parse(2, 4, "RGBR", "GBRG", "BRGB", "", ""),
        Level.parse(3, 4, "RGBY", "YRGB", "BYRG", "GBYR", "", ""),
        Level.parse(4, 4, "ROYG", "BGOR", "YBRO", "GYBR", "OBYG", "", ""),
        Level.parse(5, 4, "RPOB", "YGRP", "BOYG", "GRPO", "OBGY", "PYBR", "", ""),
        Level.parse(6, 4, "KCRP", "OYGB", "PKCO", "BRYG", "CGKY", "RBOP", "YPBC", "GORK", "", ""),
    )

    private val generated = HashMap<Int, Level>()

    /**
     * Level [number], 1-based. Numbers past the hand-made ones are generated deterministically and cached.
     * Not thread-safe: call it from one thread, such as the UI thread.
     */
    operator fun get(number: Int): Level {
        require(number >= 1) { "Level numbers start at 1, was $number" }
        return handMade.getOrNull(number - 1) ?: generated.getOrPut(number) { LevelGenerator.generate(number) }
    }
}
