package io.colorsand.ui

import androidx.compose.foundation.background
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.Spacer
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.height
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.layout.widthIn
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material3.Button
import androidx.compose.material3.ButtonDefaults
import androidx.compose.material3.Surface
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp

/** Shown over the board once the level is solved; leads to the next level. */
@Composable
fun LevelComplete(game: GameController) {
    val palette = LocalPalette.current
    Box(Modifier.fillMaxSize().background(palette.scrim), contentAlignment = Alignment.Center) {
        Surface(Modifier.widthIn(max = 320.dp).padding(24.dp), shape = RoundedCornerShape(20.dp), tonalElevation = 8.dp) {
            Column(Modifier.padding(24.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                Text("Level ${game.levelNumber} solved!", fontSize = 22.sp, fontWeight = FontWeight.Bold, color = palette.accent)
                Spacer(Modifier.height(8.dp))
                Text("${game.moveCount} moves", color = palette.dimText)
                Spacer(Modifier.height(20.dp))
                Button(
                    onClick = game::nextLevel,
                    colors = ButtonDefaults.buttonColors(containerColor = palette.accent, contentColor = palette.onAccent),
                ) { Text("Next level") }
            }
        }
    }
}
